CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,document_type VARCHAR(30) NOT NULL,document_number VARCHAR(50) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(30) NOT NULL,password_hash VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_users_email UNIQUE(email),CONSTRAINT uk_users_document UNIQUE(document_type,document_number));
